/*
 * The ai tables. drizzle-kit loads this file with its own loader (no `@repo/source` condition), so
 * it imports ONLY drizzle-orm and dependency-free relative files. Column names come from
 * `casing: 'snake_case'` (runtime + drizzle.config.ts).
 *
 * Every table and enum lives in the `ai` Postgres schema, with ai's own migration history
 * (./migrations, generated by ../../../drizzle.config.ts, bookkeeping in `ai.__drizzle_migrations`).
 * All three tables are distributed by tenant_id and colocated with every other tenant table; their
 * row-level security is row-local (0000_init): the owner is `user_id` on each row, so no policy reads
 * another table. No FK: billing and identity have none across tables either (sharding design
 * §2.1.3), and conversation_id / message_id are plain columns.
 */
import { sql } from 'drizzle-orm';
import {
  index,
  integer,
  jsonb,
  numeric,
  pgSchema,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import {
  MESSAGE_ROLES,
  MESSAGE_STATUSES,
  type MessageContent,
  USAGE_OUTCOMES,
} from '../../domain/ai.types.js';

/**
 * The `ai` Postgres schema. Exported: drizzle-kit only emits `CREATE SCHEMA` (and records it in the
 * snapshot) for exported schemas.
 */
export const aiPgSchema = pgSchema('ai');

const timestamptz = () => timestamp({ withTimezone: true, precision: 3, mode: 'date' });

export const messageRoleEnum = aiPgSchema.enum('message_role', MESSAGE_ROLES);
export const messageStatusEnum = aiPgSchema.enum('message_status', MESSAGE_STATUSES);
export const usageOutcomeEnum = aiPgSchema.enum('usage_outcome', USAGE_OUTCOMES);

// citus: tenant. One chat thread of one user.
export const conversations = aiPgSchema.table(
  'conversations',
  {
    tenantId: uuid().notNull(),
    // The application always supplies a uuidv7; the default covers raw SQL.
    id: uuid().notNull().default(sql`uuidv7()`),
    userId: uuid().notNull(),
    title: text(),
    model: text().notNull(),
    createdAt: timestamptz().notNull().defaultNow(),
    updatedAt: timestamptz().notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'conversations_tenant_id_id_pk', columns: [t.tenantId, t.id] }),
    // "My conversations, newest first": WHERE tenant_id = $1 AND user_id = $2 ORDER BY id DESC.
    index('conversations_tenant_id_user_id_id_idx').on(t.tenantId, t.userId, t.id),
  ],
);

// citus: tenant. The messages of a conversation; user_id is the conversation owner's, copied onto
// the row so the policies stay row-local. Written once (no UPDATE grant): a cut-short reply is
// stored `incomplete`.
export const messages = aiPgSchema.table(
  'messages',
  {
    tenantId: uuid().notNull(),
    id: uuid().notNull().default(sql`uuidv7()`),
    conversationId: uuid().notNull(),
    userId: uuid().notNull(),
    role: messageRoleEnum().notNull(),
    content: jsonb().$type<MessageContent>().notNull(),
    status: messageStatusEnum().notNull().default('complete'),
    model: text(),
    inputTokens: integer(),
    outputTokens: integer(),
    // Client Idempotency-Key, unique per (tenant, conversation). NULLs never collide.
    idempotencyKey: text(),
    // sha256 hex of the normalized request: the same key with another body is a conflict.
    requestHash: text(),
    createdAt: timestamptz().notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'messages_tenant_id_id_pk', columns: [t.tenantId, t.id] }),
    // The history window: WHERE tenant_id = $1 AND conversation_id = $2 ORDER BY id DESC LIMIT n.
    index('messages_tenant_id_conversation_id_id_idx').on(t.tenantId, t.conversationId, t.id),
    uniqueIndex('messages_tenant_id_conversation_id_idempotency_key_uq').on(
      t.tenantId,
      t.conversationId,
      t.idempotencyKey,
    ),
  ],
);

// citus: tenant. One row per model call, success or not: append-only (no UPDATE or DELETE grant).
// Outlives its conversation: deleting a conversation keeps its usage.
export const usage = aiPgSchema.table(
  'usage',
  {
    tenantId: uuid().notNull(),
    id: uuid().notNull().default(sql`uuidv7()`),
    userId: uuid().notNull(),
    conversationId: uuid().notNull(),
    // The assistant message the call produced; NULL when it produced none.
    messageId: uuid(),
    model: text().notNull(),
    inputTokens: integer().notNull().default(0),
    outputTokens: integer().notNull().default(0),
    // USD as OpenRouter reports it (fractions of a cent); NULL when not reported.
    costUsd: numeric({ precision: 14, scale: 8, mode: 'number' }),
    latencyMs: integer().notNull(),
    outcome: usageOutcomeEnum().notNull(),
    createdAt: timestamptz().notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ name: 'usage_tenant_id_id_pk', columns: [t.tenantId, t.id] }),
    // A user's calls in a tenant, in time order (usage reports).
    index('usage_tenant_id_user_id_id_idx').on(t.tenantId, t.userId, t.id),
  ],
);

export type ConversationRow = typeof conversations.$inferSelect;
export type MessageRow = typeof messages.$inferSelect;
export type UsageRow = typeof usage.$inferSelect;

/** Everything `DatabaseModule.forRootAsync({ schema })` needs from ai (monolith: spread it). */
export const aiSchema = {
  messageRoleEnum,
  messageStatusEnum,
  usageOutcomeEnum,
  // Prefixed: the monolith spreads every context's schema into one object.
  aiConversations: conversations,
  aiMessages: messages,
  aiUsage: usage,
};
export type AiSchema = typeof aiSchema;
